import os
import shutil
import random

# Directories
SOURCE_DIR = "D:/medical-edge-system/dataset/ecg_split"
DEST_DIR = "D:/medical-edge-system/dataset/ecg_split"
SPLIT_RATIO = 0.8  # 80% for training, 20% for validation

# The 4 classes generated by your previous script
classes = ['A', 'N', 'Q', 'V']

print("[SYSTEM] Starting dataset split (80/20)...")

# 1. Create the target directory structure
for phase in ['train', 'val']:
    for cls in classes:
        os.makedirs(os.path.join(DEST_DIR, phase, cls), exist_ok=True)

# 2. Shuffle and copy files
for cls in classes:
    src_class_dir = os.path.join(SOURCE_DIR, cls)
    if not os.path.exists(src_class_dir):
        print(f"[WARNING] Directory not found for class {cls}. Skipping.")
        continue
        
    files = os.listdir(src_class_dir)
    random.shuffle(files)  # Shuffle to randomize the data
    
    split_idx = int(len(files) * SPLIT_RATIO)
    train_files = files[:split_idx]
    val_files = files[split_idx:]
    
    print(f"[{cls}] Copying {len(train_files)} to train, {len(val_files)} to val...")
    
    for f in train_files:
        shutil.copy(os.path.join(src_class_dir, f), os.path.join(DEST_DIR, 'train', cls, f))
    for f in val_files:
        shutil.copy(os.path.join(src_class_dir, f), os.path.join(DEST_DIR, 'val', cls, f))

print("[SUCCESS] Dataset successfully split into /train and /val inside 'ecg_split'!")